ReviewRequests = {
    init: async function (app, container) {
        app = app || session.app;
        container = $(
            container ||
            '.component[name="ReviewRequests"]'
        );

        await PendingRequests.init(
            app,
            $('.component[name="PendingRequests"]', container)
        );

        await ApprovedRequests.init(
            app,
            $('.component[name="ApprovedRequests"]', container)
        );

        await RejectedRequests.init(
            app,
            $('.component[name="RejectedRequests"]', container)
        );

        $('button[data-bs-toggle="tab"]', container)
            .off("shown.bs.tab.reviewRequests")
            .on("shown.bs.tab.reviewRequests", function (e) {
                const paneSelector =
                    $(e.currentTarget).attr("data-bs-target");

                kendo.resize($(paneSelector, container));
            });
    }
};
